const body = $input.all()[0].json.body;

const nom = body.message?.toolCalls?.[0]?.function?.arguments?.nom || "";
const telephone = body.message?.toolCalls?.[0]?.function?.arguments?.telephone || "";
const date_rdv = body.message?.toolCalls?.[0]?.function?.arguments?.date_rdv || "";
const toolCallId = body.message?.toolCalls?.[0]?.id || "";

const telClean = telephone.replace(/\D/g, '');

return [{
 json: {
 nom: nom,
 telephone: telephone,
 telClean: telClean,
 date_rdv: date_rdv,
 toolCallId: toolCallId
 }
}];

const events = $input.all();
const dateVoulue = $('Code in JavaScript').first().json.date_rdv || "";

if (events.length === 0) {
 return [{ json: { error: "Aucun rendez-vous trouvé" } }];
}

if (events.length === 1) {
 return [events[0]];
}

const joursFR = ['dimanche', 'lundi', 'mardi', 'mercredi', 'jeudi', 'vendredi', 'samedi'];
const moisFR = ['janvier', 'février', 'mars', 'avril', 'mai', 'juin', 'juillet', 'août', 'septembre', 'octobre', 'novembre', 'décembre'];

const lower = dateVoulue.toLowerCase().trim();

for (const event of events) {
 const eventDate = new Date(event.json.start?.dateTime || event.json.start?.date);
 const eventJour = joursFR[eventDate.getDay()];
 const eventJourNum = eventDate.getDate();
 const eventMois = moisFR[eventDate.getMonth()];
 const eventSummary = (event.json.summary || "").toLowerCase();
 const eventDescription = (event.json.description || "").toLowerCase();

 // 1. Vérifier le nom du jour (lundi, mardi, jeudi...)
 if (lower.includes(eventJour)) {
 return [event];
 }

 // 2. Vérifier "7 mai", "11 juin"...
 if (lower.includes(eventJourNum + ' ' + eventMois)) {
 return [event];
 }

 // 3. Vérifier juste le numéro du jour ("le 7", "le 11")
 const numMatch = lower.match(/\b(\d{1,2})\b/);
 if (numMatch && parseInt(numMatch[1]) === eventJourNum) {
 return [event];
 }

 // 4. Vérifier par raison (extraction, blanchiment, nettoyage...)
 if (lower.includes('extraction') && (eventSummary.includes('extraction') || eventDescription.includes('extraction'))) {
 return [event];
 }
 if (lower.includes('blanchiment') && (eventSummary.includes('blanchiment') || eventDescription.includes('blanchiment'))) {
 return [event];
 }
 if (lower.includes('nettoyage') && (eventSummary.includes('nettoyage') || eventDescription.includes('nettoyage'))) {
 return [event];
 }
 if (lower.includes('examen') && (eventSummary.includes('examen') || eventDescription.includes('examen'))) {
 return [event];
 }
}

// Dernier recours : le plus proche dans le temps
events.sort((a, b) => {
 const dateA = new Date(a.json.start?.dateTime || a.json.start?.date);
 const dateB = new Date(b.json.start?.dateTime || b.json.start?.date);
 return dateA - dateB;
});
return [events[0]];
